[2025-04-30 00:55:20] app.CRITICAL: StackTrace : App\Service\ServicesMesDeplacements\DemandeBilletService::gestionErreurTacite() [L.693] <- App\Controller\MesDeplacements\WSDemandeBilletController::actionPatchCommandeBillet() [L.630] <- App\Controller\MesDeplacements\WSDemandeBilletController::wsPatchCommandesBillets() [L.181] <- Symfony\Component\HttpKernel\HttpKernel::handleRaw() [L.76] <- Symfony\Component\HttpKernel\HttpKernel::handle() [L.197] <- Symfony\Component\HttpKernel\Kernel::handle() [L.38]  \{"dt.trace_sampled":"true","dt.trace_id":"c73c4e84aa44cb4a4e44874a3cdb9243","dt.span_id":"6cea3d14ea09a08a"}
